export type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';

export interface SeatItem {
  kind: 'seat';
  row: number;
  column: number;
  state: SeatState;
}

export interface CouchItem {
  kind: 'couch';
  row: number;
  start: number;
  end: number;
  state: SeatState;
}

export type RowItem = SeatItem | CouchItem | { kind: 'aisle'; row: number } | { kind: 'entrance' };

export interface AuditoriumRow {
  row: number;
  items: RowItem[];
}

const LAST_ROW = 15;
const COUCH_ROW = 15;
const ENTRANCE_LAST_ROW = 10;
const ACCESSIBLE_ROW = 1;
const ACCESSIBLE_FROM = 10;
const ACCESSIBLE_TO = 15;

export function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

export function buildAuditorium(occupied: ReadonlySet<string>): AuditoriumRow[] {
  const rows: AuditoriumRow[] = [];
  for (let row = 1; row <= LAST_ROW; row++) {
    const items: RowItem[] = [];
    if (row <= ENTRANCE_LAST_ROW) {
      items.push({ kind: 'entrance' });
    } else {
      items.push(...rowBlock(row, 1, 4, occupied));
    }
    items.push({ kind: 'aisle', row });
    items.push(...rowBlock(row, 5, 20, occupied));
    items.push({ kind: 'aisle', row });
    items.push(...rowBlock(row, 21, 24, occupied));
    rows.push({ row, items });
  }
  return rows;
}

function rowBlock(row: number, from: number, to: number, occupied: ReadonlySet<string>): RowItem[] {
  const items: RowItem[] = [];
  if (row === COUCH_ROW) {
    for (let column = from; column <= to; column += 2) {
      const unavailable = occupied.has(seatId(row, column)) || occupied.has(seatId(row, column + 1));
      items.push({ kind: 'couch', row, start: column, end: column + 1, state: unavailable ? 'unavailable' : 'available' });
    }
    return items;
  }
  for (let column = from; column <= to; column++) {
    items.push({ kind: 'seat', row, column, state: seatState(row, column, occupied) });
  }
  return items;
}

function seatState(row: number, column: number, occupied: ReadonlySet<string>): SeatState {
  if (occupied.has(seatId(row, column))) {
    return 'unavailable';
  }
  const accessible = row === ACCESSIBLE_ROW && column >= ACCESSIBLE_FROM && column <= ACCESSIBLE_TO;
  return accessible ? 'accessible' : 'available';
}

