import { Component, computed, inject } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { ActivatedRoute, Router } from '@angular/router';
import { catchError, EMPTY, map, switchMap } from 'rxjs';
import { CinescopeApi } from '../api';
import { showDate } from '../dates';
import { Movie, Screening } from '../models';
import { AuditoriumRow, buildAuditorium } from './auditorium';

interface SeatMapData {
  screening: Screening;
  movie: Movie;
}

@Component({
  selector: 'app-seat-selection',
  template: `
    @let data = view();
    @if (data) {
      <h1 data-testid="seat-map-title">Choose your seats</h1>
      <p class="subtitle" data-testid="seat-map-subtitle">Show Date: {{ showDateText() }}</p>
      <p class="limit" data-testid="seat-limit-info">You can reserve up to 10 seats per reservation</p>

      <div class="screen" data-testid="screen-indicator">SCREEN</div>

      <div class="seat-map" data-testid="seat-map">
        @for (row of rows(); track row.row) {
          <div class="seat-row" data-testid="seat-row" [attr.data-row]="row.row">
            <span class="row-label" data-testid="row-label-left" [attr.data-row]="row.row">{{ row.row }}</span>
            @for (item of row.items; track $index) {
              @if (item.kind === 'seat') {
                <button
                  type="button"
                  class="seat"
                  data-testid="seat"
                  [attr.data-row]="item.row"
                  [attr.data-column]="item.column"
                  [attr.data-state]="item.state"
                  [disabled]="item.state === 'unavailable'"
                >{{ item.column }}</button>
              } @else if (item.kind === 'couch') {
                <button
                  type="button"
                  class="couch"
                  data-testid="couch"
                  [attr.data-row]="item.row"
                  [attr.data-column-start]="item.start"
                  [attr.data-column-end]="item.end"
                  [attr.data-state]="item.state"
                  [disabled]="item.state === 'unavailable'"
                >{{ item.start }}-{{ item.end }}</button>
              } @else if (item.kind === 'aisle') {
                <span class="aisle" data-testid="aisle" [attr.data-row]="item.row"></span>
              } @else {
                <span class="entrance"></span>
              }
            }
            <span class="row-label" data-testid="row-label-right" [attr.data-row]="row.row">{{ row.row }}</span>
          </div>
        }
      </div>
    }
  `,
  styles: `
    :host {
      display: block;
      padding: 24px;
      text-align: center;
      font-family: Roboto, 'Helvetica Neue', sans-serif;
    }

    h1 {
      margin: 0 0 4px;
      font-size: 28px;
    }

    .subtitle {
      margin: 0 0 8px;
    }

    .limit {
      margin: 0 0 16px;
    }

    .screen {
      width: 60%;
      margin: 0 auto 24px;
      padding: 6px 0;
      background: #e0e0e0;
      border-radius: 0 0 50% 50% / 0 0 20px 20px;
      letter-spacing: 6px;
      font-weight: 500;
    }

    .seat-map {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 6px;
    }

    .seat-row {
      display: flex;
      align-items: center;
    }

    .row-label {
      width: 32px;
      font-size: 13px;
    }

    .seat,
    .couch {
      height: 28px;
      margin: 0 2px;
      padding: 0;
      border: 0;
      border-radius: 4px;
      color: #fff;
      font-size: 11px;
      cursor: pointer;
    }

    .seat {
      width: 28px;
    }

    .couch {
      width: 60px;
    }

    .seat:disabled,
    .couch:disabled {
      cursor: not-allowed;
    }

    .seat[data-state='available'],
    .couch[data-state='available'] {
      background: #2e7d32;
    }

    .seat[data-state='accessible'] {
      background: #1565c0;
    }

    .seat[data-state='unavailable'],
    .couch[data-state='unavailable'] {
      background: #c62828;
    }

    .aisle {
      width: 64px;
      flex: none;
    }

    .entrance {
      width: 128px;
      flex: none;
    }
  `,
})
export class SeatSelection {
  private readonly api = inject(CinescopeApi);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);

  protected readonly view = toSignal(
    this.api.screening(Number(this.route.snapshot.paramMap.get('id'))).pipe(
      switchMap((screening) =>
        this.api.movie(screening.movieId).pipe(map((movie): SeatMapData => ({ screening, movie }))),
      ),
      catchError(() => {
        void this.router.navigate(['/']);
        return EMPTY;
      }),
    ),
  );

  protected readonly showDateText = computed(() => {
    const data = this.view();
    return data ? showDate(data.screening.date, data.screening.time) : '';
  });

  protected readonly rows = computed<AuditoriumRow[]>(() => {
    const data = this.view();
    return data ? buildAuditorium(new Set(data.screening.occupiedSeats)) : [];
  });
}

